import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def latent_samples(ctx):
    latent = torch.randn(4, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(latent)}
dataset = synth.Spec("stylegan-path-length", generator=latent_samples, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class TinyGenerator(nn.Module):
    def __init__(self):
        super().__init__()
        self.mapping = build("mlp", "tiny", in_features=4, out_features=2)
        self.synthesis = build("mlp", "tiny", in_features=2, out_features=192)
    def forward(self, inputs):
        styles = self.mapping(inputs)
        images = self.synthesis(styles).reshape(-1, 3, 8, 8)
        return {"images": images, "styles": styles}
trainer = Trainer(TinyGenerator(), train, recipe="structured-objective", recipe_config={"loss": "stylegan-path-length", "loss_kwargs": {"target_scale": 0.0, "weight": 1.0}, "bindings": {"logits_or_prediction": {"output": "images"}, "targets": {"output": "styles"}}}, batch_size=2, max_epochs=1, device="cpu")
trainer.fit()
